<script setup lang="ts">
import type { ApiProblem } from '~/types/api'
definePageMeta({ middleware: 'auth' }); const route = useRoute(); const id = Number(route.params.id); const { find, syncCurriculum } = usePrograms(); const { get } = useLookups(); const [{ data: program }, { data: lookups }] = await Promise.all([useAsyncData(`program-${id}`, () => find(id)), useAsyncData('curriculum-lookups', get)]); if (!program.value) throw createError({ statusCode: 404 })
const courses = ref((program.value.program_courses ?? []).map(item => ({ course_id: item.course_id, year_level: item.year_level, semester: item.semester }))); const saving = ref(false); const errorMessage = ref('')
function addCourse() { courses.value.push({ course_id: lookups.value?.courses[0]?.id ?? 0, year_level: 1, semester: 'first_semester' }) }
async function saveCurriculum() { saving.value = true; errorMessage.value = ''; try { program.value = await syncCurriculum(id, courses.value) } catch (error) { errorMessage.value = (error as ApiProblem).message } finally { saving.value = false } }
</script>
<template><div v-if="program" class="page-shell"><PageHeader :title="program.code" :description="program.name"><template #actions><StatusBadge :status="program.status" /><BaseButton :to="`/programs/${program.id}/edit`">Edit program</BaseButton></template></PageHeader><BaseCard><div class="mb-5 flex items-center justify-between gap-4 border-b border-[#e5ecf3] pb-5"><div><h2 class="font-semibold text-[#102a43]">Curriculum editor</h2><p class="text-sm text-[#60728a]">Courses are synchronized as one transaction.</p></div><BaseButton variant="secondary" @click="addCourse">Add course</BaseButton></div><div class="space-y-3"><div v-for="(item, index) in courses" :key="index" class="grid gap-3 sm:grid-cols-[1fr_140px_180px_auto]"><BaseSelect :id="`curriculum-course-${index}`" v-model="item.course_id" :options="(lookups?.courses ?? []).map(course => ({ label: `${course.course_code} · ${course.course_title}`, value: course.id }))" /><BaseSelect :id="`curriculum-year-${index}`" v-model="item.year_level" :options="[1, 2, 3, 4, 5].map(value => ({ label: `Year ${value}`, value }))" /><BaseSelect :id="`curriculum-semester-${index}`" v-model="item.semester" :options="[{ label: 'First semester', value: 'first_semester' }, { label: 'Second semester', value: 'second_semester' }, { label: 'Summer', value: 'summer' }]" /><BaseButton variant="ghost" @click="courses.splice(index, 1)">Remove</BaseButton></div></div><p v-if="errorMessage" class="mt-4 text-sm text-red-600">{{ errorMessage }}</p><div class="mt-5 flex justify-end"><BaseButton :loading="saving" @click="saveCurriculum">Save curriculum</BaseButton></div></BaseCard></div></template>
